# Composite search: run keyword + phonetic scorers, fuse with reciprocal rank fusion.
def kw_score(query, text):
    qt = set(query.lower().split()); dt = set(text.lower().split())
    return len(qt & dt) / len(qt) if qt else 0.0
def soundex(w):
    w = w.upper(); m = {"BFPV": "1", "CGJKQSXZ": "2", "DT": "3", "L": "4", "MN": "5", "R": "6"}
    code = w[0]; prev = ""
    for ch in w[1:]:
        d = next((v for k, v in m.items() if ch in k), "")
        if d and d != prev: code += d
        prev = d
    return code
def phon_score(query, text):
    qc = {soundex(w) for w in query.split()}
    tc = {soundex(w) for w in text.split()}
    return len(qc & tc) / len(qc) if qc else 0.0
docs = {'d1': 'John Smith', 'd2': 'Jon Smyth', 'd3': 'Jane Doe'}
query = "Jon Smith"
rankings = []
for name, fn in [("keyword", kw_score), ("phonetic", phon_score)]:
    ranked = sorted(docs, key=lambda d: fn(query, docs[d]), reverse=True)
    rankings.append(ranked)
    print(name, "ranking:", ranked)
rrf = {}
for ranked in rankings:
    for i, d in enumerate(ranked):
        rrf[d] = rrf.get(d, 0) + 1.0 / (60 + i)
print("fused (RRF, k=60):", sorted(rrf, key=rrf.get, reverse=True))

